import React from "react";
import { getLogoFilter, getLogoSource } from "../lib/branding";

/**
 * Renders the organisation logo with an optional CSS color filter applied.
 * The filter approach works on any image type (PNG, JPG, SVG) — including
 * logos that do NOT have a transparent background — unlike the old mask trick
 * which would just fill the entire bounding box with color.
 */
export default function LogoMark({ settings, className = "w-10 h-10", alt = "Insapi Marketing" }) {
  const src = getLogoSource(settings);
  const filter = getLogoFilter(settings);

  return (
    <img
      src={src}
      alt={alt}
      className={`shrink-0 object-contain ${className}`}
      style={{ filter }}
    />
  );
}
