import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import { api } from "./api";

export const DEFAULT_LOGO_URL = `${process.env.PUBLIC_URL || ""}/logo.png`;
export const DEFAULT_BRAND_NAME = "Insapi Marketing";

const BrandingContext = createContext({
  branding: {
    name: DEFAULT_BRAND_NAME,
    logo_url: DEFAULT_LOGO_URL,
    logo_filter: "none",
    logo_custom_color: "",
  },
  setBranding: () => {},
});

export function getLogoSource(settings = {}) {
  return settings.logo_url || DEFAULT_LOGO_URL;
}

/**
 * Convert a hex color string to the CSS filter chain that colorises any image
 * (including ones without transparency) to that color.
 * Strategy: brightness(0) turns every pixel black, then invert+sepia+saturate+hue-rotate
 * shifts it to the target hue.
 */
function hexToFilter(hex) {
  // Parse r,g,b from #rrggbb
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);

  // Convert to HSL to derive hue-rotate and saturation amounts
  const rn = r / 255, gn = g / 255, bn = b / 255;
  const max = Math.max(rn, gn, bn);
  const min = Math.min(rn, gn, bn);
  const l = (max + min) / 2;
  let h = 0, s = 0;

  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case rn: h = ((gn - bn) / d + (gn < bn ? 6 : 0)) / 6; break;
      case gn: h = ((bn - rn) / d + 2) / 6; break;
      case bn: h = ((rn - gn) / d + 4) / 6; break;
      default: break;
    }
  }

  const hueDeg = Math.round(h * 360);
  const satPct = Math.round(s * 100);
  // lightness: map 0..1 to brightness filter (darker colors need less brightness boost)
  const brightnessPct = Math.round(l * 200); // 0 = black, 100 = original, 200 = white

  // We first zero the image to black, then use sepia + saturate + hue-rotate to reach the target
  // sepia(1) gives a warm brown (~36° hue, ~75% sat, ~50% lightness starting point)
  // We then hue-rotate by (hueDeg - 36) to arrive at the target hue
  const hueRotate = hueDeg - 36;
  const saturate = satPct > 0 ? Math.max(Math.round((satPct / 75) * 100), 100) : 0;
  const brightness = brightnessPct > 0 ? Math.round(brightnessPct * 0.8) : 50;

  return `brightness(0) saturate(100%) invert(${Math.round(l * 100)}%) sepia(1) saturate(${saturate}%) hue-rotate(${hueRotate}deg) brightness(${brightness}%)`;
}

export function getLogoFilter(settings = {}) {
  switch (settings.logo_filter) {
    case "grayscale":
      return "grayscale(1)";
    case "blue":
      return hexToFilter("#1D4ED8");
    case "red":
      return hexToFilter("#DC2626");
    case "green":
      return hexToFilter("#059669");
    case "custom": {
      const hex = settings.logo_custom_color || "";
      return /^#[0-9a-f]{6}$/i.test(hex) ? hexToFilter(hex) : "none";
    }
    default:
      return "none";
  }
}

// Kept for backward compatibility but no longer drives a separate render path
export function isCustomLogoColor(_settings = {}) {
  return false;
}

export function getLogoColor(_settings = {}) {
  return "";
}

export function BrandingProvider({ children }) {
  const [branding, setBranding] = useState({
    name: DEFAULT_BRAND_NAME,
    logo_url: DEFAULT_LOGO_URL,
    logo_filter: "none",
    logo_custom_color: "",
  });

  useEffect(() => {
    let mounted = true;
    api.get("/settings")
      .then((response) => {
        if (mounted) setBranding(response.data);
      })
      .catch(() => {});
    return () => {
      mounted = false;
    };
  }, []);

  const value = useMemo(() => ({ branding, setBranding }), [branding]);

  return <BrandingContext.Provider value={value}>{children}</BrandingContext.Provider>;
}

export function useBranding() {
  return useContext(BrandingContext);
}
